    ["talk.zone.4B.04"]="كي يدوم الهواء... قلتُ لكِ.",
    ["talk.zone.4C.01"]="شبكات المصرف ۱ ملتوية نحو الخارج.",
    ["talk.zone.4C.02"]="كانت إينيس تقول إن هناك شيئًا ضخمًا في غرفة المراوح. لا أحد يدخلها وحده.",
    ["talk.zone.4C.03"]="ابقي على الخط يا نوا.",
    ["talk.zone.4D.01"]="كان شيء ضخم يصرخ. هل كان ذلك بسببكِ؟",
    ["talk.zone.4D.02"]="لم يعد موجودًا.",
    ["talk.zone.4E.01"]="هل أنتِ عند المراوح؟ ذهبت أمي إلى هناك.",
    ["talk.zone.4E.02"]="كان معها مصباح أصفر.",
    ["talk.zone.4E.03"]="...",
    ["talk.zone.4E.04"]="نوا...",
    ["talk.zone.4E.05"]="... نوا؟ من يتحدث إلى نوا؟",
    ["talk.zone.4F.01"]="هل هي حية؟",
    ["talk.zone.4F.02"]="نعم، إنها على الخط. نوا، هناك من يريد التحدث إليكِ.",
    ["talk.zone.4F.03"]="نوا، أنا أمكِ.",
    ["talk.zone.4F.04"]="... أمي؟",
    ["talk.zone.4F.05"]="تأخرتِ كثيرًا.",
    ["talk.zone.4F.06"]="أعرف، كنتُ عالقة.",
    ["talk.zone.4F.07"]="ما زلتُ أعدّ.",
    ["talk.zone.4F.08"]="استمري في العدّ. نحن في الطريق.",
    ["talk.zone.4F.09"]="يوهان! إنها أمي!",
    ["talk.zone.4F.10"]="اسحبي ذلك الذراع وانطلقي.",
    ["talk.zone.4G.01"]="المراوح!",
    ["talk.zone.4G.02"]="يقول يوهان إنها لا تصلح هواءنا. ليس ما دام الماء عند الباب.",
    ["talk.zone.4G.03"]="لكن صوتها جميل.",
    ["talk.zone.4H.01"]="انخفض! وضعتُ علامة على النافذة.",
    ["talk.zone.4H.02"]="الساعة ۱٦:۱۲.",
    ["talk.zone.4H.03"]="سأجلس بجانب الراديو الآن.",
    ["talk.zone.4I.01"]="أشعر بالنعاس.",
    ["talk.zone.4I.02"]="عاد يوهان إلى النوم.",
    ["talk.zone.4I.03"]="سأترك الراديو يعمل... كي تسمعيني عند الباب.",
    ["talk.zone.4I.04"]="... ثلاثمئة وستة... ثلاثمئة وسبعة...",
    ["talk.zone.4J.01"]="نوا، انخفض الماء. أنا قادمة.",
    ["talk.zone.4J.02"]="نوا؟",
    ["talk.zone.4K.01"]="... انخفض الماء.",
    ["talk.zone.4K.02"]="إنها نائمة. تحتاج إلى هواء.",
    ["talk.zone.4K.03"]="سأدير... العجلة.",
    ["talk.zone.4L.01"]="أتمنى أن تعيش ذكرياتك...",
    ["talk.zone.4L.02"]="... إلى الأبد...",
    ["talk.zone.4M.01"]="مصعد السطح. الصعود في الساعة ۱۸:۰۰.",
    ["talk.zone.4M.02"]="أنا نوا. أنا في ماتريكس ۱۳، في الأسفل تمامًا، قرب المضخات.",
    ["talk.zone.4M.03"]="وصل الماء إلى منتصف الباب، والمراوح...",
    ["talk.zone.4N.01"]="... نوا؟",
    ["talk.zone.4N.02"]="...",
    ["talk.zone.4N.03"]="نوا... يمكنكِ التوقف عن العدّ الآن.",
    ["boss.Lion"]="الأسد",
    ["boss.Gardener"]="البستاني",
    ["speaker.Noa"]="نوا",
    ["speaker.Yohan"]="يوهان",
    ["speaker.Mila"]="ميلا",
}
